@deco.set_separate_app_context(application_name=SIMDIALOGS_APP_NAME)
def check_sim_collimator_kv_source_arm_locked_checkbox() -> None:
    """Locates the main Sim Dialogs window > then left mouse click on the kV Source Arm Locked Checkbox only if its enabled and unchecked
    """
    if SimDialogMainFuncs.find_main_sim_dialogs_window() and not CommonActions.get_checkbox_state(SimDialogsObjects.sim_Collimator_KV_Source_Arm_Locked_CheckBox):
        CommonActions.left_click_object_no_move(SimDialogsObjects.sim_Collimator_KV_Source_Arm_Locked_CheckBox)

@deco.set_separate_app_context(application_name=SIMDIALOGS_APP_NAME)
def uncheck_sim_collimator_kv_source_arm_locked_checkbox() -> None:
    """Locates the main Sim Dialogs window > then left mouse click on the kV Source Arm Locked Checkbox only if its enabled and checked
    """
    if SimDialogMainFuncs.find_main_sim_dialogs_window() and CommonActions.get_checkbox_state(SimDialogsObjects.sim_Collimator_KV_Source_Arm_Locked_CheckBox):
        CommonActions.left_click_object_no_move(SimDialogsObjects.sim_Collimator_KV_Source_Arm_Locked_CheckBox)

